<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue'
import type {QueryDocumentSnapshot} from 'firebase/firestore'
import {mayWriteLive} from '../integrations/firebase/stagingConfig'
import {stagingSession} from '../integrations/firebase/stagingSession'
import {listTickets,createTicket,readReplies,replyTicket,changeTicketStatus,type Ticket,type Reply} from '../integrations/firestore/platform'
import {accountKey,ticketStateLabel,ticketStates,type TicketState} from '../features/platform/platformModel'
const p=defineProps<{platform?:boolean}>()
const rows=ref<Ticket[]>([]),selected=ref<Ticket|null>(null),replies=ref<Reply[]>([]),busy=ref(false),error=ref(''),ready=ref(false),more=ref(false),replyMore=ref(false)
const type=ref('problema'),subject=ref(''),text=ref(''),reply=ref(''),status=ref<TicketState>('open'),sentId=ref('')
let cursor:QueryDocumentSnapshot|undefined,replyCursor:QueryDocumentSnapshot|undefined,alive=true,epoch=0
onUnmounted(()=>{alive=false;epoch++})
async function load(append=false){if(busy.value)return;busy.value=true;error.value='';const n=epoch;try{const r=await listTickets(!!p.platform,append?cursor:undefined);if(!alive||n!==epoch)return;rows.value=[...(append?rows.value:[]),...r.rows].sort((a,b)=>b.createdAt-a.createdAt);cursor=r.cursor;more.value=r.more;ready.value=true;if(selected.value){const current=rows.value.find(x=>x.id===selected.value?.id);if(current){selected.value=current;status.value=current.status}else if(!append){selected.value=null;replies.value=[]}}}catch(e){if(n===epoch)error.value=(e as Error).message}finally{if(n===epoch)busy.value=false}}
async function open(t:Ticket,append=false){if(busy.value)return;busy.value=true;error.value='';const n=epoch;if(!append){selected.value=t;replies.value=[];reply.value='';status.value=t.status;replyMore.value=false;replyCursor=undefined}try{const data=await readReplies(t.id,!!p.platform,append?replyCursor:undefined);if(!alive||n!==epoch)return;replies.value=[...(append?replies.value:[]),...data.rows];replyCursor=data.cursor;replyMore.value=data.more}catch(e){if(n===epoch)error.value=(e as Error).message}finally{if(n===epoch)busy.value=false}}
async function submit(){if(busy.value||p.platform)return;busy.value=true;error.value='';try{sentId.value=await createTicket(type.value,subject.value,text.value,accountKey(stagingSession.value));subject.value='';text.value=''}catch(e){error.value=(e as Error).message}finally{busy.value=false}if(sentId.value)await load()}
async function send(){const t=selected.value;if(!t||busy.value)return;busy.value=true;error.value='';let success=false;try{await replyTicket(t.id,!!p.platform,reply.value);success=true}catch(e){error.value=(e as Error).message}finally{busy.value=false}if(success)await open(t)}
async function update(){const t=selected.value;if(!t||busy.value)return;busy.value=true;error.value='';let ok=false;try{await changeTicketStatus(t.id,status.value);t.status=status.value;ok=true}catch(e){error.value=(e as Error).message}finally{busy.value=false}if(ok)await load()}
watch(()=>stagingSession.value?.uid,()=>{epoch++;rows.value=[];selected.value=null;replies.value=[];ready.value=false;busy.value=false;cursor=undefined;sentId.value='';if(stagingSession.value)void load()});onMounted(()=>void load())
</script>
<template><section class="panel lf14-tickets"><h2>{{platform?'Assistenza LionFit':'Le mie richieste di assistenza'}}</h2><p v-if="!platform" class="muted small">Le richieste arrivano al gestore LionFit. Le email automatiche non sono ancora attive. Non inserire dati sanitari, password o informazioni non necessarie.</p><form v-if="!platform" class="stack" @submit.prevent="submit"><label>Tipo<select v-model="type"><option value="problema">Problema</option><option value="suggerimento">Suggerimento</option><option value="account">Account</option><option value="altro">Altro</option></select></label><label>Oggetto<input v-model="subject" required maxlength="100"/></label><label>Messaggio<textarea v-model="text" required minlength="2" maxlength="1800" rows="4"/></label><button class="primary" :disabled="busy||!mayWriteLive()">Apri richiesta</button><p v-if="sentId" class="notice">Richiesta registrata · ID {{sentId}}</p></form><div class="row between"><h3>Richieste</h3><button type="button" class="secondary" :disabled="busy" @click="load()">Aggiorna</button></div><p v-if="error" role="alert" class="notice">{{error}}</p><p v-if="!ready&&!error" class="muted">Caricamento…</p><p v-else-if="ready&&!rows.length" class="muted">Nessuna richiesta.</p><button v-for="t in rows" :key="t.id" class="secondary lf14-ticket-row" :disabled="busy" @click="open(t)"><span><strong>{{t.subject}}</strong><small>{{platform?t.requesterName+' · '+t.gymId:''}} · {{t.createdAt?new Date(t.createdAt).toLocaleDateString('it-IT'):'Data non disponibile'}}</small></span><span>{{ticketStateLabel(t.status)}}</span></button><button v-if="more" class="secondary" :disabled="busy" @click="load(true)">Carica altre richieste</button><article v-if="selected" class="lf14-ticket-detail"><div class="row between"><h3>{{selected.subject}}</h3><button class="secondary" :disabled="busy" @click="selected=null">Chiudi</button></div><small>ID {{selected.id}} · {{ticketStateLabel(selected.status)}}</small><small v-if="platform">Account richiedente: {{selected.requesterId}} · Palestra: {{selected.gymId}}</small><p class="lf14-ticket-text">{{selected.message}}</p><div v-for="r in replies" :key="r.id" class="lf14-reply"><strong>{{r.author==='platform'?'Assistenza LionFit':'Richiedente'}}</strong><small>{{r.createdAt?new Date(r.createdAt).toLocaleString('it-IT'):''}}</small><p class="lf14-ticket-text">{{r.message}}</p></div><button v-if="replyMore" class="secondary" :disabled="busy" @click="open(selected,true)">Altri messaggi</button><form v-if="selected.status!=='resolved'" class="stack" @submit.prevent="send"><label>Rispondi<textarea v-model="reply" required minlength="2" maxlength="1800" rows="3"/></label><button class="primary" :disabled="busy||!mayWriteLive()">Invia risposta</button></form><div v-if="platform" class="stack"><label>Stato<select v-model="status"><option v-for="s in ticketStates" :key="s" :value="s">{{ticketStateLabel(s)}}</option></select></label><button class="secondary" :disabled="busy||!mayWriteLive()||status===selected.status" @click="update">Aggiorna stato</button></div></article></section></template>
